'use strict';

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { URL } = require('node:url');

const { createState, submitWord, checkRate, cloudView } = require('./wordcloud.js');

const PUBLIC_DIR = path.join(__dirname, 'public');
const INDEX_HTML_PATH = path.join(PUBLIC_DIR, 'index.html');
const CLIENT_JS_PATH = path.join(PUBLIC_DIR, 'client.js');
const STYLE_CSS_PATH = path.join(PUBLIC_DIR, 'style.css');

const MAX_BODY_BYTES = 1024;
const LONG_POLL_TIMEOUT_MS = 20000;

function sendJson(res, statusCode, obj, extraHeaders) {
  const body = JSON.stringify(obj);
  const headers = Object.assign({
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body),
  }, extraHeaders || {});
  res.writeHead(statusCode, headers);
  res.end(body);
}

function sendFile(res, filePath, contentType) {
  let data;
  try {
    data = fs.readFileSync(filePath);
  } catch (err) {
    sendJson(res, 404, { error: 'not_found' });
    return;
  }
  res.writeHead(200, {
    'Content-Type': contentType,
    'Content-Length': data.length,
  });
  res.end(data);
}

function readBody(req, maxBytes) {
  return new Promise((resolve, reject) => {
    let total = 0;
    const chunks = [];
    let aborted = false;

    req.on('data', (chunk) => {
      if (aborted) return;
      total += chunk.length;
      if (total > maxBytes) {
        aborted = true;
        reject(Object.assign(new Error('too_large'), { code: 'TOO_LARGE' }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });

    req.on('end', () => {
      if (aborted) return;
      resolve(Buffer.concat(chunks).toString('utf8'));
    });

    req.on('error', (err) => {
      if (aborted) return;
      aborted = true;
      reject(err);
    });
  });
}

function createServer(state) {
  const appState = state || createState();
  const waiters = [];

  function notifyWaiters() {
    while (waiters.length) {
      const waiter = waiters.pop();
      clearTimeout(waiter.timer);
      if (waiter.req && typeof waiter.onClose === 'function') {
        waiter.req.removeListener('close', waiter.onClose);
      }
      try {
        waiter.resolve();
      } catch (e) {
        // ignore
      }
    }
  }

  function handleLongPoll(req, res, since) {
    const currentVersion = appState.version;
    if (currentVersion > since) {
      sendJson(res, 200, cloudView(appState, { now: Date.now() }));
      return;
    }

    let settled = false;

    const finish = () => {
      if (settled) return;
      settled = true;
      sendJson(res, 200, cloudView(appState, { now: Date.now() }));
    };

    const waiter = { resolve: finish };
    const timer = setTimeout(() => {
      removeWaiter();
      finish();
    }, LONG_POLL_TIMEOUT_MS);
    waiter.timer = timer;

    function removeWaiter() {
      const idx = waiters.indexOf(waiter);
      if (idx !== -1) waiters.splice(idx, 1);
    }

    const onClose = () => {
      settled = true;
      clearTimeout(timer);
      removeWaiter();
    };
    waiter.req = req;
    waiter.onClose = onClose;
    req.on('close', onClose);

    waiters.push(waiter);
  }

  const server = http.createServer((req, res) => {
    let parsedUrl;
    try {
      parsedUrl = new URL(req.url, 'http://localhost');
    } catch (err) {
      sendJson(res, 400, { error: 'bad_request' });
      return;
    }
    const pathname = parsedUrl.pathname;

    try {
      if (pathname === '/') {
        if (req.method !== 'GET') {
          sendJson(res, 405, { error: 'method_not_allowed' });
          return;
        }
        sendFile(res, INDEX_HTML_PATH, 'text/html');
        return;
      }

      if (pathname === '/client.js') {
        if (req.method !== 'GET') {
          sendJson(res, 405, { error: 'method_not_allowed' });
          return;
        }
        sendFile(res, CLIENT_JS_PATH, 'application/javascript');
        return;
      }

      if (pathname === '/style.css') {
        if (req.method !== 'GET') {
          sendJson(res, 405, { error: 'method_not_allowed' });
          return;
        }
        sendFile(res, STYLE_CSS_PATH, 'text/css');
        return;
      }

      if (pathname === '/api/cloud') {
        if (req.method !== 'GET') {
          sendJson(res, 405, { error: 'method_not_allowed' });
          return;
        }
        const sinceRaw = parsedUrl.searchParams.get('since');
        const sinceNum = Number(sinceRaw);
        const since = sinceRaw === null || sinceRaw === '' || Number.isNaN(sinceNum) ? -1 : sinceNum;
        handleLongPoll(req, res, since);
        return;
      }

      if (pathname === '/api/words') {
        if (req.method !== 'POST') {
          sendJson(res, 405, { error: 'method_not_allowed' });
          return;
        }
        readBody(req, MAX_BODY_BYTES).then((bodyText) => {
          let parsed;
          try {
            parsed = JSON.parse(bodyText);
          } catch (err) {
            sendJson(res, 400, { ok: false, error: 'bad_json' });
            return;
          }

          const clientIdHeader = req.headers['x-client-id'];
          const clientId = (typeof clientIdHeader === 'string' && clientIdHeader.trim() !== '')
            ? clientIdHeader
            : 'anonymous';

          const rate = checkRate(appState, clientId, Date.now());
          if (!rate.allowed) {
            const retryAfterSec = Math.max(1, Math.ceil(rate.retryAfterMs / 1000));
            sendJson(res, 429, {
              ok: false,
              error: 'rate_limited',
              retryAfterMs: rate.retryAfterMs,
            }, { 'Retry-After': String(retryAfterSec) });
            return;
          }

          const word = parsed && typeof parsed === 'object' ? parsed.word : undefined;
          const result = submitWord(appState, word, Date.now());
          if (!result.ok) {
            sendJson(res, 400, { ok: false, error: result.error });
            return;
          }

          const view = cloudView(appState, { now: Date.now() });
          sendJson(res, 200, { ok: true, word: result.word, view });
          notifyWaiters();
        }).catch((err) => {
          if (err && err.code === 'TOO_LARGE') {
            sendJson(res, 413, { ok: false, error: 'too_large' });
            return;
          }
          sendJson(res, 400, { ok: false, error: 'bad_request' });
        });
        return;
      }

      sendJson(res, 404, { error: 'not_found' });
    } catch (err) {
      sendJson(res, 500, { error: 'internal_error' });
    }
  });

  return server;
}

function start(port) {
  const state = createState();
  const server = createServer(state);
  const actualPort = port || process.env.PORT || 3000;
  server.listen(actualPort, '0.0.0.0', () => {
    console.log(`word cloud listening on http://0.0.0.0:${actualPort}`);
  });
  return { server, port: actualPort };
}

module.exports = { createServer, start };

if (require.main === module) {
  start(process.env.PORT || 3000);
}

'use strict';

// Pure word-cloud logic, validation and view model.
// No I/O, no timers, no global mutable state — everything is passed in.

function createState() {
  return {
    counts: {},
    total: 0,
    version: 0,
    events: [],
    clients: {},
  };
}

function normaliseWord(raw) {
  if (typeof raw !== 'string') return null;
  let s = raw.trim().toLowerCase();
  if (s === '') return null;
  // Strip everything except a-z, 0-9, apostrophe and hyphen.
  s = s.replace(/[^a-z0-9'-]/g, '');
  // Collapse runs of hyphens/apostrophes to a single character.
  s = s.replace(/[-']{2,}/g, (m) => m[0]);
  // Strip leading/trailing hyphens/apostrophes.
  s = s.replace(/^[-']+|[-']+$/g, '');
  if (s === '') return null;
  if (s.length > 24) return null;
  return s;
}

function submitWord(state, raw, now = Date.now()) {
  if (typeof raw !== 'string') {
    return { ok: false, error: 'not_a_string' };
  }
  const trimmed = raw.trim();
  if (trimmed === '') {
    return { ok: false, error: 'empty' };
  }
  if (trimmed.length > 24) {
    return { ok: false, error: 'too_long' };
  }
  const word = normaliseWord(raw);
  if (word === null) {
    return { ok: false, error: 'invalid' };
  }

  state.counts[word] = (state.counts[word] || 0) + 1;
  state.total += 1;
  state.version += 1;
  state.events.push({ word, at: now });
  if (state.events.length > 500) {
    state.events = state.events.slice(-500);
  }

  return { ok: true, word, version: state.version };
}

function checkRate(state, clientId, now = Date.now(), opts = {}) {
  const { limit = 12, windowMs = 60000 } = opts;
  const id = clientId && String(clientId).trim() !== '' ? String(clientId) : 'anonymous';

  if (!state.clients[id]) {
    state.clients[id] = [];
  }
  const kept = state.clients[id].filter((t) => now - t < windowMs);
  state.clients[id] = kept;

  if (kept.length >= limit) {
    const oldest = kept[0];
    const retryAfterMs = Math.max(1, oldest + windowMs - now);
    return { allowed: false, retryAfterMs };
  }

  kept.push(now);
  return { allowed: true };
}

function topWords(state, limit = 120) {
  const arr = Object.keys(state.counts).map((word) => ({
    word,
    count: state.counts[word],
  }));

  arr.sort((a, b) => {
    if (b.count !== a.count) return b.count - a.count;
    if (a.word < b.word) return -1;
    if (a.word > b.word) return 1;
    return 0;
  });

  return arr.slice(0, limit).map((item, i) => ({
    word: item.word,
    count: item.count,
    rank: i + 1,
  }));
}

function scaleSizes(items, minPx = 14, maxPx = 84) {
  if (!items || items.length === 0) return [];

  const counts = items.map((i) => i.count);
  const minCount = Math.min(...counts);
  const maxCount = Math.max(...counts);

  return items.map((item) => {
    let weight;
    if (items.length === 1 || maxCount === minCount) {
      weight = 1;
    } else {
      weight =
        (Math.sqrt(item.count) - Math.sqrt(minCount)) /
        (Math.sqrt(maxCount) - Math.sqrt(minCount));
    }
    const size = Math.round(minPx + weight * (maxPx - minPx));
    return {
      word: item.word,
      count: item.count,
      rank: item.rank,
      size,
      weight,
    };
  });
}

function recentActivity(state, now = Date.now(), buckets = 20, bucketMs = 15000) {
  const result = [];
  const windowStart = now - buckets * bucketMs;

  for (let i = 0; i < buckets; i++) {
    const from = windowStart + i * bucketMs;
    const to = from + bucketMs;
    result.push({ index: i, from, to, count: 0 });
  }

  const events = (state && state.events) || [];
  for (const ev of events) {
    if (!ev) continue;
    if (ev.at >= windowStart && ev.at < now) {
      let idx = Math.floor((ev.at - windowStart) / bucketMs);
      if (idx >= buckets) idx = buckets - 1;
      if (idx < 0) idx = 0;
      result[idx].count += 1;
    }
  }

  return result;
}

function cloudView(state, opts = {}) {
  const now = opts && opts.now !== undefined ? opts.now : Date.now();
  const limit = opts && opts.limit !== undefined ? opts.limit : 120;
  const minPx = opts && opts.minPx !== undefined ? opts.minPx : 14;
  const maxPx = opts && opts.maxPx !== undefined ? opts.maxPx : 84;

  let sized = [];
  let activity = [];
  try {
    const top = topWords(state, limit);
    sized = scaleSizes(top, minPx, maxPx);
  } catch (e) {
    sized = [];
  }
  try {
    activity = recentActivity(state, now);
  } catch (e) {
    activity = [];
  }

  const unique = state && state.counts ? Object.keys(state.counts).length : 0;
  const total = (state && state.total) || 0;
  const version = (state && state.version) || 0;

  return {
    version,
    total,
    unique,
    words: sized,
    activity,
    leader: sized.length ? sized[0].word : null,
    updatedAt: now,
  };
}

module.exports = {
  createState,
  normaliseWord,
  submitWord,
  checkRate,
  topWords,
  scaleSizes,
  recentActivity,
  cloudView,
};

