'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');

const {
  createState,
  normaliseWord,
  submitWord,
  checkRate,
  topWords,
  scaleSizes,
  recentActivity,
  cloudView,
} = require('./wordcloud.js');

test('createState returns fresh JSON-serialisable state', () => {
  const state = createState();
  assert.deepEqual(state, {
    counts: {},
    total: 0,
    version: 0,
    events: [],
    clients: {},
  });
  assert.doesNotThrow(() => JSON.stringify(state));
});

test('normaliseWord: mixed case and punctuation', () => {
  assert.equal(normaliseWord('Hello!'), 'hello');
  assert.equal(normaliseWord('  Hi There  '), 'hithere');
  assert.equal(normaliseWord("Rock'n'Roll"), "rock'n'roll");
});

test('normaliseWord: emoji-only input returns null', () => {
  assert.equal(normaliseWord('😀😀😀'), null);
  assert.equal(normaliseWord('🚀'), null);
});

test('normaliseWord: 25-char word returns null (too long)', () => {
  const word25 = 'a'.repeat(25);
  assert.equal(normaliseWord(word25), null);
});

test('normaliseWord: non-string input returns null', () => {
  assert.equal(normaliseWord(42), null);
  assert.equal(normaliseWord(null), null);
  assert.equal(normaliseWord(undefined), null);
  assert.equal(normaliseWord({}), null);
  assert.equal(normaliseWord(['a']), null);
});

test('normaliseWord: collapses and trims hyphens/apostrophes', () => {
  assert.equal(normaliseWord('--hi--'), 'hi');
  assert.equal(normaliseWord("''hi''"), 'hi');
  assert.equal(normaliseWord('a---b'), 'a-b');
});

test('normaliseWord: nasty script input is safe charset or null', () => {
  const result = normaliseWord('<script>Hi</script>');
  if (result !== null) {
    assert.match(result, /^[a-z0-9'-]+$/);
  } else {
    assert.equal(result, null);
  }
});

test('submitWord bumps version and total, accumulates counts', () => {
  const state = createState();
  const r1 = submitWord(state, 'Hello!', 1000);
  assert.equal(r1.ok, true);
  assert.equal(r1.word, 'hello');
  assert.equal(r1.version, 1);
  assert.equal(state.total, 1);
  assert.equal(state.version, 1);
  assert.equal(state.counts.hello, 1);

  const r2 = submitWord(state, 'hello', 2000);
  assert.equal(r2.ok, true);
  assert.equal(state.total, 2);
  assert.equal(state.version, 2);
  assert.equal(state.counts.hello, 2);
  assert.equal(state.events.length, 2);
  assert.equal(state.events[1].at, 2000);
});

test('submitWord error cases', () => {
  const state = createState();
  assert.equal(submitWord(state, 42).error, 'not_a_string');
  assert.equal(submitWord(state, '   ').error, 'empty');
  assert.equal(submitWord(state, 'a'.repeat(25)).error, 'too_long');
  assert.equal(submitWord(state, '!!!').error, 'invalid');
  assert.equal(state.total, 0);
  assert.equal(state.version, 0);
});

test('submitWord caps events at 500', () => {
  const state = createState();
  for (let i = 0; i < 510; i++) {
    submitWord(state, 'word' + (i % 5), i);
  }
  assert.equal(state.events.length, 500);
});

test('checkRate allows up to limit then blocks with positive retryAfterMs, resets after window', () => {
  const state = createState();
  let now = 0;
  for (let i = 0; i < 12; i++) {
    const r = checkRate(state, 'client-a', now, { limit: 12, windowMs: 60000 });
    assert.equal(r.allowed, true);
    now += 100;
  }
  const blocked = checkRate(state, 'client-a', now, { limit: 12, windowMs: 60000 });
  assert.equal(blocked.allowed, false);
  assert.ok(blocked.retryAfterMs >= 1);

  // After the window has passed, allowed again.
  const later = now + 60000 + 1;
  const allowedAgain = checkRate(state, 'client-a', later, { limit: 12, windowMs: 60000 });
  assert.equal(allowedAgain.allowed, true);
});

test('checkRate treats missing/blank clientId as anonymous', () => {
  const state = createState();
  const r1 = checkRate(state, undefined, 0);
  const r2 = checkRate(state, '   ', 100);
  assert.equal(r1.allowed, true);
  assert.equal(r2.allowed, true);
  assert.ok(state.clients.anonymous.length === 2);
});

test('topWords sorts by count desc, then word asc for ties', () => {
  const state = createState();
  submitWord(state, 'zebra', 1);
  submitWord(state, 'apple', 2);
  submitWord(state, 'mango', 3);
  submitWord(state, 'apple', 4); // apple now count 2

  const top = topWords(state);
  assert.equal(top[0].word, 'apple');
  assert.equal(top[0].count, 2);
  assert.equal(top[0].rank, 1);
  // zebra and mango tie at count 1, mango < zebra alphabetically
  assert.equal(top[1].word, 'mango');
  assert.equal(top[2].word, 'zebra');
});

test('topWords respects limit', () => {
  const state = createState();
  for (let i = 0; i < 10; i++) submitWord(state, 'w' + i, i);
  const top = topWords(state, 3);
  assert.equal(top.length, 3);
});

test('scaleSizes gives top word exactly maxPx', () => {
  const items = [
    { word: 'a', count: 10, rank: 1 },
    { word: 'b', count: 5, rank: 2 },
    { word: 'c', count: 1, rank: 3 },
  ];
  const sized = scaleSizes(items, 14, 84);
  assert.equal(sized[0].size, 84);
  assert.equal(sized[0].weight, 1);
  assert.ok(sized[2].size < sized[0].size);
});

test('scaleSizes single-word cloud gives valid size', () => {
  const items = [{ word: 'solo', count: 3, rank: 1 }];
  const sized = scaleSizes(items, 14, 84);
  assert.equal(sized.length, 1);
  assert.equal(sized[0].weight, 1);
  assert.equal(sized[0].size, 84);
  assert.ok(sized[0].size >= 14 && sized[0].size <= 84);
});

test('scaleSizes empty input returns []', () => {
  assert.deepEqual(scaleSizes([]), []);
});

test('recentActivity returns exactly `buckets` entries, oldest first', () => {
  const state = createState();
  const now = 100000;
  submitWord(state, 'hi', now - 1000);
  const activity = recentActivity(state, now, 20, 15000);
  assert.equal(activity.length, 20);
  assert.equal(activity[0].index, 0);
  assert.equal(activity[19].index, 19);
  assert.ok(activity[0].from < activity[19].from);
  const total = activity.reduce((sum, b) => sum + b.count, 0);
  assert.equal(total, 1);
});

test('recentActivity with no events returns zero counts, still full length', () => {
  const state = createState();
  const activity = recentActivity(state, Date.now(), 20, 15000);
  assert.equal(activity.length, 20);
  for (const b of activity) {
    assert.equal(b.count, 0);
  }
});

test('cloudView on empty state returns safe defaults', () => {
  const state = createState();
  const view = cloudView(state, { now: 12345 });
  assert.equal(view.version, 0);
  assert.equal(view.total, 0);
  assert.equal(view.unique, 0);
  assert.deepEqual(view.words, []);
  assert.equal(view.leader, null);
  assert.equal(view.updatedAt, 12345);
  assert.equal(view.activity.length, 20);
});

test('cloudView never throws even on malformed state', () => {
  assert.doesNotThrow(() => cloudView({}));
  assert.doesNotThrow(() => cloudView(null));
  assert.doesNotThrow(() => cloudView(undefined));
});

test('cloudView returns exact shape and word entries have all fields', () => {
  const state = createState();
  submitWord(state, 'hello', 1);
  submitWord(state, 'hello', 2);
  submitWord(state, 'world', 3);
  const view = cloudView(state, { now: 9999 });
  assert.deepEqual(Object.keys(view).sort(), [
    'activity',
    'leader',
    'total',
    'unique',
    'updatedAt',
    'version',
    'words',
  ]);
  assert.equal(view.leader, 'hello');
  assert.equal(view.total, 3);
  assert.equal(view.unique, 2);
  for (const w of view.words) {
    assert.ok('word' in w);
    assert.ok('count' in w);
    assert.ok('rank' in w);
    assert.ok('size' in w);
    assert.ok('weight' in w);
  }
});

(function () {
  'use strict';

  function getClientId() {
    var key = 'wordcloud-client-id';
    try {
      var existing = localStorage.getItem(key);
      if (existing) return existing;
      var id;
      if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        id = crypto.randomUUID();
      } else {
        id = 'id-' + Math.random().toString(36).slice(2) + '-' + Date.now().toString(36);
      }
      localStorage.setItem(key, id);
      return id;
    } catch (err) {
      return 'anonymous';
    }
  }

  var clientId = getClientId();
  var lastVersion = -1;
  var pollController = null;

  var form = document.getElementById('submit-form');
  var input = document.getElementById('word-input');
  var statusEl = document.getElementById('status');
  var cloudEl = document.getElementById('cloud');
  var activityEl = document.getElementById('activity');
  var statTotal = document.getElementById('stat-total');
  var statUnique = document.getElementById('stat-unique');
  var statLeader = document.getElementById('stat-leader');

  function setStatus(text) {
    statusEl.textContent = text || '';
  }

  function render(view) {
    if (!view) return;
    lastVersion = view.version;

    cloudEl.textContent = '';
    var words = view.words || [];
    for (var i = 0; i < words.length; i++) {
      var w = words[i];
      var span = document.createElement('span');
      span.style.fontSize = w.size + 'px';
      span.title = String(w.count);
      span.textContent = w.word;
      cloudEl.appendChild(span);
    }

    activityEl.textContent = '';
    var activity = view.activity || [];
    var maxCount = 1;
    for (var j = 0; j < activity.length; j++) {
      if (activity[j].count > maxCount) maxCount = activity[j].count;
    }
    for (var k = 0; k < activity.length; k++) {
      var bar = document.createElement('div');
      var pct = Math.max(4, Math.round((activity[k].count / maxCount) * 100));
      bar.style.height = pct + '%';
      activityEl.appendChild(bar);
    }

    statTotal.textContent = 'total: ' + view.total;
    statUnique.textContent = 'unique: ' + view.unique;
    statLeader.textContent = 'leader: ' + (view.leader || '-');
  }

  function submitWord(word) {
    setStatus('');
    return fetch('/api/words', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-client-id': clientId,
      },
      body: JSON.stringify({ word: word }),
    }).then(function (res) {
      return res.json().then(function (data) {
        if (!res.ok || !data.ok) {
          var msg = data && data.error ? data.error : 'error';
          if (data && data.error === 'rate_limited') {
            msg = 'slow down, try again shortly';
          }
          setStatus(msg);
          return;
        }
        render(data.view);
        setStatus('');
      });
    }).catch(function () {
      setStatus('reconnecting…');
    });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var word = input.value;
    if (!word || !word.trim()) {
      setStatus('empty');
      return;
    }
    submitWord(word).then(function () {
      input.value = '';
      input.focus();
    });
  });

  function pollLoop() {
    fetch('/api/cloud?since=' + lastVersion)
      .then(function (res) {
        if (!res.ok) throw new Error('bad response');
        return res.json();
      })
      .then(function (view) {
        render(view);
        setStatus('');
        setTimeout(pollLoop, 0);
      })
      .catch(function () {
        setStatus('reconnecting…');
        setTimeout(pollLoop, 2000);
      });
  }

  function loadInitial() {
    fetch('/api/cloud')
      .then(function (res) {
        return res.json();
      })
      .then(function (view) {
        render(view);
        setStatus('');
        pollLoop();
      })
      .catch(function () {
        setStatus('reconnecting…');
        setTimeout(loadInitial, 2000);
      });
  }

  loadInitial();
})();

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { createServer } = require('./server.js');
const { createState } = require('./wordcloud.js');

let server;
let baseUrl;

test.before(async () => {
  server = createServer(createState());
  await new Promise((resolve) => {
    server.listen(0, '127.0.0.1', resolve);
  });
  const port = server.address().port;
  baseUrl = `http://127.0.0.1:${port}`;
});

test.after(async () => {
  await new Promise((resolve) => server.close(resolve));
});

test('GET / returns 200 html with cloud div', async () => {
  const res = await fetch(`${baseUrl}/`);
  assert.equal(res.status, 200);
  const text = await res.text();
  assert.match(text, /id="cloud"/);
});

test('GET /api/cloud on fresh server returns total 0 words []', async () => {
  const res = await fetch(`${baseUrl}/api/cloud`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.total, 0);
  assert.deepEqual(body.words, []);
});

test('POST /api/words normalises Node! to node', async () => {
  const res = await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerA' },
    body: JSON.stringify({ word: 'Node!' }),
  });
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.ok, true);
  assert.equal(body.view.words[0].word, 'node');
});

test('posting node twice makes count 2 and version bumps', async () => {
  const res1 = await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerB' },
    body: JSON.stringify({ word: 'node' }),
  });
  const body1 = await res1.json();
  const versionAfterFirst = body1.view.version;

  const res2 = await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerB' },
    body: JSON.stringify({ word: 'node' }),
  });
  const body2 = await res2.json();

  const nodeEntry = body2.view.words.find((w) => w.word === 'node');
  assert.ok(nodeEntry);
  assert.ok(nodeEntry.count >= 2);
  assert.equal(body2.view.version, versionAfterFirst + 1);
});

test('POST with blank word returns 400 with error string', async () => {
  const res = await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerC' },
    body: JSON.stringify({ word: '   ' }),
  });
  assert.equal(res.status, 400);
  const body = await res.json();
  assert.equal(body.ok, false);
  assert.equal(typeof body.error, 'string');
});

test('POST with body over 1KB returns 413', async () => {
  const bigWord = 'x'.repeat(2048);
  const res = await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerD' },
    body: JSON.stringify({ word: bigWord }),
  });
  assert.equal(res.status, 413);
  const body = await res.json();
  assert.equal(body.ok, false);
  assert.equal(body.error, 'too_large');
});

test('13th submission from same client within window gets 429 with Retry-After', async () => {
  const clientId = 'rate-limited-client';
  let lastRes;
  for (let i = 0; i < 13; i++) {
    lastRes = await fetch(`${baseUrl}/api/words`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-client-id': clientId },
      body: JSON.stringify({ word: 'word' + i }),
    });
  }
  assert.equal(lastRes.status, 429);
  assert.ok(lastRes.headers.get('retry-after'));
  const body = await lastRes.json();
  assert.equal(body.ok, false);
  assert.equal(body.error, 'rate_limited');
});

test('GET /api/cloud?since=0 returns immediately after a submit bumped version', async () => {
  await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerE' },
    body: JSON.stringify({ word: 'sinceword' }),
  });
  const res = await fetch(`${baseUrl}/api/cloud?since=0`);
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.ok(body.version > 0);
});

test('GET /nope returns 404', async () => {
  const res = await fetch(`${baseUrl}/nope`);
  assert.equal(res.status, 404);
  const body = await res.json();
  assert.equal(body.error, 'not_found');
});

test('long poll at current version is pending then resolves after a submit', async () => {
  const stateRes = await fetch(`${baseUrl}/api/cloud`);
  const stateBody = await stateRes.json();
  const currentVersion = stateBody.version;

  let resolved = false;
  const pollPromise = fetch(`${baseUrl}/api/cloud?since=${currentVersion}`).then((res) => {
    resolved = true;
    return res.json();
  });

  await new Promise((resolve) => setTimeout(resolve, 200));
  assert.equal(resolved, false, 'long poll should still be pending after 200ms');

  await fetch(`${baseUrl}/api/words`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-client-id': 'testerF' },
    body: JSON.stringify({ word: 'longpollword' }),
  });

  const result = await pollPromise;
  assert.ok(resolved);
  assert.ok(result.version > currentVersion);
});

'use strict';

function createState() {
  return { counts: {}, total: 0, version: 0, events: [], clients: {} };
}

function normaliseWord(raw) {
  if (typeof raw !== 'string') return null;
  let s = raw.trim().toLowerCase();
  if (s.length === 0) return null;
  if (s.length > 24) return null;
  s = s.replace(/[^a-z0-9'-]/g, '');
  s = s.replace(/-+/g, '-').replace(/'+/g, "'");
  s = s.replace(/^[-']+/, '').replace(/[-']+$/, '');
  if (s.length === 0) return null;
  if (s.length > 24) return null;
  return s;
}

function submitWord(state, raw, now) {
  now = now === undefined ? Date.now() : now;
  if (typeof raw !== 'string') return { ok: false, error: 'not_a_string' };
  const trimmed = raw.trim();
  if (trimmed.length === 0) return { ok: false, error: 'empty' };
  if (trimmed.length > 24) return { ok: false, error: 'too_long' };
  const word = normaliseWord(raw);
  if (word === null) return { ok: false, error: 'invalid' };
  state.counts[word] = (state.counts[word] || 0) + 1;
  state.total += 1;
  state.version += 1;
  state.events.push({ word, at: now });
  if (state.events.length > 500) {
    state.events = state.events.slice(state.events.length - 500);
  }
  return { ok: true, word, version: state.version };
}

function checkRate(state, clientId, now, opts) {
  const options = Object.assign({ limit: 12, windowMs: 60000 }, opts || {});
  const id = (clientId && String(clientId).trim()) || 'anonymous';
  if (!state.clients[id]) state.clients[id] = [];
  const windowStart = now - options.windowMs;
  state.clients[id] = state.clients[id].filter((t) => t > windowStart);
  const arr = state.clients[id];
  if (arr.length >= options.limit) {
    const oldest = arr[0];
    const retryAfterMs = Math.max(1, oldest + options.windowMs - now);
    return { allowed: false, retryAfterMs };
  }
  arr.push(now);
  return { allowed: true };
}

function topWords(state, limit) {
  limit = limit === undefined ? 120 : limit;
  const words = Object.keys(state.counts);
  words.sort((a, b) => {
    const cb = state.counts[b] - state.counts[a];
    if (cb !== 0) return cb;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
  });
  return words.slice(0, limit).map((word, i) => ({
    word,
    count: state.counts[word],
    rank: i + 1,
  }));
}

function scaleSizes(items, minPx, maxPx) {
  minPx = minPx === undefined ? 14 : minPx;
  maxPx = maxPx === undefined ? 84 : maxPx;
  if (!items || items.length === 0) return [];
  const counts = items.map((it) => it.count);
  const minCount = Math.min(...counts);
  const maxCount = Math.max(...counts);
  return items.map((it) => {
    let weight;
    if (maxCount === minCount || items.length === 1) {
      weight = 1;
    } else {
      weight = (Math.sqrt(it.count) - Math.sqrt(minCount)) / (Math.sqrt(maxCount) - Math.sqrt(minCount));
    }
    const size = Math.round(minPx + weight * (maxPx - minPx));
    return { word: it.word, count: it.count, rank: it.rank, size, weight };
  });
}

function recentActivity(state, now, buckets, bucketMs) {
  buckets = buckets === undefined ? 20 : buckets;
  bucketMs = bucketMs === undefined ? 15000 : bucketMs;
  const result = [];
