    if (ev.at < windowStart || ev.at >= now) continue;
    const idx = Math.floor((ev.at - windowStart) / bucketMs);
    if (idx >= 0 && idx < buckets) {
      result[idx].count += 1;
    }
  }
  return result;
}

function cloudView(state, opts) {
  const options = opts || {};
  const now = options.now === undefined ? Date.now() : options.now;
  const limit = options.limit === undefined ? 120 : options.limit;
  const minPx = options.minPx === undefined ? 14 : options.minPx;
  const maxPx = options.maxPx === undefined ? 84 : options.maxPx;

  const top = topWords(state, limit);
  const words = scaleSizes(top, minPx, maxPx);
  const activity = recentActivity(state, now);
  const leader = words.length > 0 ? words[0].word : null;

  return {
    version: state.version,
    total: state.total,
    unique: Object.keys(state.counts).length,
    words,
    activity,
    leader,
    updatedAt: now,
  };
}

module.exports = {
  createState,
  normaliseWord,
  submitWord,
  checkRate,
  topWords,
  scaleSizes,
  recentActivity,
  cloudView,
};

